tool_input.command:
Write-Output "=== winget 相关进程 ==="
Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match 'winget|Ollama|ollama' } | Select-Object Id,ProcessName,@{n='Mem(MB)';e={[int]($_.WorkingSet/1MB)}},StartTime
Write-Output "=== Ollama 是否已落到磁盘 ==="
foreach($p in @("$env:LOCALAPPDATA\Programs\Ollama\ollama.exe","C:\Program Files\Ollama\ollama.exe","$env:LOCALAPPDATA\Ollama")){ if(Test-Path $p){"  存在: $p"}else{"  无: $p"} }
Write-Output "=== ollama 命令 ==="
$x=Get-Command ollama -ErrorAction SilentlyContinue; if($x){"  ollama -> $($x.Source)"}else{"  未在 PATH"}

Write-Output "=== winget 子进程/网络 ==="
Get-Process -Id 3584 -ErrorAction SilentlyContinue | Select-Object Id,ProcessName,@{n='CPU';e={$_.CPU}},@{n='Mem(MB)';e={[int]($_.WorkingSet/1MB)}}
Write-Output "=== 下载临时目录大小(winget缓存) ==="
$wc="$env:LOCALAPPDATA\Temp\WinGet"
if(Test-Path $wc){ $sz=(Get-ChildItem $wc -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum; "  WinGet 缓存: $([int]($sz/1MB)) MB" } else { "  无 WinGet 临时目录" }
Write-Output "=== 再等 60s 看缓存是否增长 ==="
Start-Sleep -Seconds 60
if(Test-Path $wc){ $sz2=(Get-ChildItem $wc -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum; "  60s 后: $([int]($sz2/1MB)) MB" }
Get-Process -Id 3584 -ErrorAction SilentlyContinue | Select-Object Id,@{n='CPU';e={$_.CPU}}

# 杀掉残留 winget 进程
Get-Process winget -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Write-Output "=== 测 Ollama 官方下载源连通 ==="
try{ $r=Invoke-WebRequest "https://ollama.com/download/OllamaSetup.exe" -Method Head -UseBasicParsing -TimeoutSec 20; "  OllamaSetup.exe: status=$($r.StatusCode) size=$([int]($r.Headers['Content-Length']/1MB))MB" }catch{ "  FAIL: $($_.Exception.Message.Split([char]10)[0])" }
Write-Output "=== scoop 是否已初始化 ==="
$s=Get-Command scoop -ErrorAction SilentlyContinue; if($s){"  scoop 可用"}else{"  scoop 无"}

$dst="$env:TEMP\OllamaSetup.exe"
Write-Output "下载到: $dst"
$ProgressPreference='SilentlyContinue'
try{
  Invoke-WebRequest "https://ollama.com/download/OllamaSetup.exe" -OutFile $dst -UseBasicParsing -TimeoutSec 1800
  $sz=(Get-Item $dst).Length
  Write-Output "下载完成: $([int]($sz/1MB)) MB"
}catch{ Write-Output "下载失败: $($_.Exception.Message)" }

$sp="C:\Program Files\Python310\lib\site-packages\openviking"
foreach($f in @("config\embedding.py","config\vlm.py")){
  Write-Output "==================== $f ===================="
  Get-Content "$sp\$f" -Encoding UTF8 -ErrorAction SilentlyContinue | Select-Object -First 90
}

$sp="C:\Program Files\Python310\lib\site-packages"
Write-Output "=== openviking_cli config 目录 ==="
Get-ChildItem "$sp\openviking_cli\utils\config" -File -ErrorAction SilentlyContinue | Select-Object Name
Write-Output "=== VLMConfig / embedding 字段定义 ==="
foreach($f in @("vlm_config.py","open_viking_config.py")){
  if(Test-Path "$sp\openviking_cli\utils\config\$f"){ "--- $f ---"; Get-Content "$sp\openviking_cli\utils\config\$f" -Encoding UTF8 | Select-String -Pattern "class |provider|model|api_base|api_key|dimension|workspace|endpoint|annotation|: str|: int" | Select-Object -First 40 | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" } }
}

$sp="C:\Program Files\Python310\lib\site-packages"
Write-Output "=== embedding_config.py 字段 ==="
Get-Content "$sp\openviking_cli\utils\config\embedding_config.py" -Encoding UTF8 | Select-String -Pattern "class |provider|model|api_base|api_key|dimension|: str|: int|Literal|ollama|local" | Select-Object -First 40 | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" }
Write-Output "=== local_embedders 支持哪些 provider ==="
Get-Content "$sp\openviking\models\embedder\local_embedders.py" -Encoding UTF8 -ErrorAction SilentlyContinue | Select-String -Pattern "class |provider|ollama|sentence|huggingface|def __init__" | Select-Object -First 25 | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" }
Write-Output "=== embedder 工厂支持列表 ==="
Get-Content "$sp\openviking\models\embedder\__init__.py" -Encoding UTF8 -ErrorAction SilentlyContinue | Select-String -Pattern "ollama|openai|volcengine|litellm|local|dashscope|provider ==|elif" | Select-Object -First 30 | ForEach-Object { "  L$($_.LineNumber): $($_.Line.Trim())" }

$raw = Get-Content "$env:USERPROFILE\.dsh\.credentials.yaml" -Encoding UTF8 -Raw
$m = [regex]::Match($raw, 'MAGPIE_GATEWAY_KEY:\s*["'']?([^"''\r\n]+)["'']?')
$mk = if($m.Success){$m.Groups[1].Value.Trim()}else{$null}
Write-Output "MAGPIE_GATEWAY_KEY = '$mk' (len=$($mk.Length))"
# 实测 key 能否调 magpie
$h=@{ "Authorization"="Bearer $mk"; "Content-Type"="application/json" }
$body=@{ model="auto/hy3"; messages=@(@{role="user";content="hi"}); max_tokens=5 } | ConvertTo-Json
try{ $r=Invoke-RestMethod "http://127.0.0.1:3425/v1/chat/completions" -Method Post -Headers $h -Body $body -TimeoutSec 30; "magpie chat OK: $($r.choices[0].message.content)" }catch{ "magpie chat FAIL: $($_.Exception.Message.Split([char]10)[0])" }

Write-Output "=== ov.conf JSON 合法性 ==="
try{ Get-Content "$env:USERPROFILE\.openviking\ov.conf" -Raw | ConvertFrom-Json | Out-Null; "JSON OK" }catch{ "JSON 错误: $($_.Exception.Message)" }
Write-Output "=== openviking-server doctor (config 阶段) ==="
openviking-server doctor 2>&1 | Select-Object -First 40
Write-Output "=== Ollama 下载 ==="
$dst="$env:TEMP\OllamaSetup.exe"; if(Test-Path $dst){ "$([int]((Get-Item $dst).Length/1MB)) MB" }
